        reader = csv.DictReader(handle)
        if reader.fieldnames != EXPECTED_FIELDS:
            errors.append("line 1: header must be name,age,email,country")
        for line_number, row in enumerate(reader, start=2):
            name = (row.get("name") or "").strip()
            age_text = (row.get("age") or "").strip()
            email = (row.get("email") or "").strip()
            country = (row.get("country") or "").strip()
            if not name:
                errors.append(f"line {line_number}: name is required")
            elif len(name) > 40:
                errors.append(f"line {line_number}: name is too long")
            try:
                age = int(age_text)
                if age < 18 or age > 65:
                    raise ValueError
            except ValueError:
                errors.append(f"line {line_number}: age must be an integer from 18 through 65")
            if not EMAIL.fullmatch(email):
                errors.append(f"line {line_number}: email is invalid")
            if not country:
                errors.append(f"line {line_number}: country is required")
            elif len(country) > 2:
                errors.append(f"line {line_number}: country must be at most 2 characters")
